<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useRoute, useRouter } from 'vue-router'
import { api } from '../../api'

const router = useRouter()
const route = useRoute()
const market = ref(route.query.market==='US'?'US':'CN')
watch(()=>route.query.market,value=>{market.value=value==='US'?'US':'CN';category.value='';selected.value=[];void query()})
function changeMarket(){category.value='';selected.value=[];void query()}
const loading = ref(false), detailLoading = ref(false), supplierRefreshing = ref(false)
const items = ref<any[]>([]), total = ref(0), page = ref(1), pageSize = ref(50)
const search = ref(''), supplier = ref(''), category = ref(''), status = ref('')
const selected = ref<any[]>([]), detail = ref<any>(), drawer = ref(false), categories = ref<any[]>([])
const managedCategories = ref<any[]>([]), categoryLoading = ref(false)
const detailTitle = ref('POD 产品详情'), detailTab = ref('overview'), categoryOpen = ref(false), exactEditOpen = ref(false), variantEditOpen = ref(false)
  const wbOpen = ref(false), wbLoading = ref(false), wbSubmitting = ref(false), wbTemplates = ref<any[]>([]), wbStores = ref<any[]>([]), wbExports = ref<any[]>([]), wbTemplateFile = ref<File>()
const wbVariantRows = ref<any[]>([])
const wbTemplateForm = reactive({ subject_name: '', subject_id: undefined as number | undefined })
const wbForm = reactive({ product_ids: [] as string[], store_id: '', template_id: '', brand: 'Нет бренда', requirement: '', price_cny: undefined as number | undefined, variant_selection: 'all', variant_ids: [] as string[] })
let detailRequest = 0
let listRequest = 0
const summary = reactive({ products: 0, variants: 0, current_assets: 0, local_assets: 0, oss_assets: 0, versions: 0, compositions: 0, by_status: {} as Record<string, number>, by_supplier: {} as Record<string, number> })
const exactForm = reactive<any>({})
const variantForms = ref<any[]>([])
const totalPages = computed(() => Math.max(1, Math.ceil(total.value / pageSize.value)))
const galleryUrls = computed(() => (detail.value?.assets || []).map(imageUrl))
const currentVersion = computed(() => detail.value?.versions?.find((row: any) => row.is_current) || detail.value?.versions?.[0])
const supplierDescription = computed(() => detail.value?.source_snapshot?.product_description || {})
const supplierPrintAreas = computed(() => supplierDescription.value?.print_areas || detail.value?.source_snapshot?.print_areas || [])
const supplierSizeAttributes = computed(() => {
  const definitions = new Map((detail.value?.source_snapshot?.size_attr_map || []).map((row: any) => [Number(row.id), row]))
  const sizes = new Map((detail.value?.source_snapshot?.sizes || []).map((row: any) => [Number(row.id || row.size_id), row]))
  return (detail.value?.source_snapshot?.size_attr_info || []).map((row: any) => ({ ...row, attribute: definitions.get(Number(row.attr_id)), size: sizes.get(Number(row.size_id)) }))
})
const roleLabel: Record<string, string> = { main: '主效果图', mockup: '效果图', artwork: '印花原图', source: '生产原图', sku: 'SKU 图', additional: '附图' }
const statusLabel: Record<string, string> = { ready: '在用', draft: '待整理', archived: '已归档', completed: '已完成', failed: '失败', paused: '已暂停', queued: '等待中' }
const libraryStateLabel: Record<string, string> = { ready: '可生产且可发布', production_incomplete: '生产资料待补充', publication_incomplete: '上架资料待补充', archived: '已归档' }

function imageUrl(link: any) { return link.asset.oss_url || `/api/v1/assets/${link.asset.id}/content` }
function formatDate(value: string) { return value ? new Date(value).toLocaleString('zh-CN') : '-' }
function showValue(value: unknown, suffix = '') { return value === null || value === undefined || value === '' ? '-' : `${value}${suffix}` }
function formatBytes(value: number) { if (!value) return '-'; if (value < 1024 * 1024) return `${Math.round(value / 1024)} KB`; return `${(value / 1024 / 1024).toFixed(1)} MB` }
function effective(row: any, variantKey: string, productKey: string) { return row?.[variantKey] ?? detail.value?.[productKey] }
function supplierPackage(row: any) { const value = row?.properties || {}; return [value.length, value.width, value.height].every(item => item !== undefined && item !== null) ? `${value.length} × ${value.width} × ${value.height}` : '-' }

async function loadSummary() { try { Object.assign(summary, await api.get<any>('/pod/library/summary')) } catch { /* 列表仍可单独使用 */ } }
async function load() {
  const requestId = ++listRequest
  loading.value = true
  try {
    const q = new URLSearchParams({ page: String(page.value), page_size: String(pageSize.value), search: search.value, supplier: supplier.value, category: category.value, status: status.value, market: market.value })
    const [list, cats] = await Promise.all([api.get<any>(`/pod/library/products?${q}`), api.get<any>(`/pod/library/categories?market=${market.value}`)])
    if (requestId !== listRequest) return
    items.value = list.items; total.value = list.total; categories.value = cats.items
  } catch (error: any) { if (requestId === listRequest) ElMessage.error(error?.message || 'POD 产品读取失败') }
  finally { if (requestId === listRequest) loading.value = false }
  void loadSummary()
}
async function loadManagedCategories() {
  categoryLoading.value = true
  try { managedCategories.value = (await api.get<any>('/pod/library/categories')).items }
  catch (error: any) { ElMessage.error(error?.message || '分类读取失败') }
  finally { categoryLoading.value = false }
}
async function openCategoryManager() { categoryOpen.value = true; await loadManagedCategories() }
async function query() { page.value = 1; await load() }
async function show(row: any) {
  const requestId = ++detailRequest
  detailTitle.value = row.name || row.sku || 'POD 产品详情'; detail.value = undefined; detailTab.value = 'overview'; drawer.value = true; detailLoading.value = true
  try { const value = await api.get<any>(`/pod/library/products/${row.id}`); if (requestId === detailRequest) detail.value = value }
  catch (error: any) { if (requestId === detailRequest) { drawer.value = false; ElMessage.error(error?.message || '产品详情读取失败') } }
  finally { if (requestId === detailRequest) detailLoading.value = false }
}
function openExactEdit() {
  if (!detail.value) return
  Object.assign(exactForm, { name: detail.value.name, category: detail.value.category, supplier: detail.value.supplier, supplier_product_id: detail.value.supplier_product_id, purchase_price_cny: detail.value.purchase_price_cny, domestic_delivery_cny: detail.value.domestic_delivery_cny, currency: detail.value.currency || 'CNY', package_length_mm: detail.value.package_length_mm, package_width_mm: detail.value.package_width_mm, package_height_mm: detail.value.package_height_mm, package_weight_g: detail.value.package_weight_g, description_category_id: detail.value.description_category_id, type_id: detail.value.type_id, category_display: detail.value.category_display, notes: detail.value.notes })
  exactEditOpen.value = true
}
async function saveExactFacts() {
  await api.patch<any>(`/catalog/products/${detail.value.id}`, { ...exactForm })
  detail.value = await api.get<any>(`/pod/library/products/${detail.value.id}`); exactEditOpen.value = false
  ElMessage.success('准确资料已保存；后续发布会优先使用这些字段'); await load()
}
function openVariantEdit() { variantForms.value = (detail.value?.variants || []).map((row: any) => ({ ...row, properties: { ...(row.properties || {}) } })); variantEditOpen.value = true }
async function saveVariantFacts() {
  await api.put<any>(`/catalog/products/${detail.value.id}/variants`, variantForms.value)
  detail.value = await api.get<any>(`/pod/library/products/${detail.value.id}`); variantEditOpen.value = false
  ElMessage.success('SKU 准确资料已保存'); await load()
}
async function refreshSupplierFacts() {
  supplierRefreshing.value = true
  try {
    const result = await api.post<any>(`/pod/library/products/${detail.value.id}/refresh-supplier`, {})
    detail.value = result.product
    const index = items.value.findIndex(row => row.id === detail.value.id)
    if (index >= 0) items.value[index] = { ...items.value[index], ...result.product }
    ElMessage.success(`资料已写回原产品，共更新 ${result.variants_updated} 个原有 SKU；未新建 SKU`)
  } catch (error: any) { ElMessage.error(error?.message || '供应商资料更新失败') }
  finally { supplierRefreshing.value = false }
}
async function openFolder() { try { await api.post(`/pod/library/products/${detail.value.id}/open-folder`, {}); ElMessage.success('已打开产品文件夹') } catch (error: any) { ElMessage.error(error?.message || '产品文件夹无法打开') } }
async function restore() { const result = await api.post<any>(`/pod/library/products/${detail.value.id}/restore`, {}); ElMessage.success('恢复任务已进入任务中心'); window.location.href = `/jobs?job=${result.job.id}` }
async function setProductStatus(value: string) { await api.patch<any>(`/catalog/products/${detail.value.id}`, { status: value }); detail.value = await api.get<any>(`/pod/library/products/${detail.value.id}`); ElMessage.success(value === 'archived' ? '产品已归档' : '产品已恢复为可发布'); await load() }
async function batchCategory() { if (!selected.value.length) return ElMessage.warning('请先勾选产品'); const value = await ElMessageBox.prompt('输入分类名称；留空可移出分类', '批量设置分类', { inputValue: category.value, confirmButtonText: '保存', cancelButtonText: '取消' }).catch(() => null); if (!value) return; await api.patch('/pod/library/products/batch-category', { product_ids: selected.value.map(item => item.id), category: value.value.trim() }); ElMessage.success(`已更新 ${selected.value.length} 个产品`); selected.value = []; await load() }
function publishToOzon(product?: any) {
  const products = product ? [product] : selected.value
  if (!products.length) return ElMessage.warning('请先勾选要上架到 OZON 的 POD 产品')
  const unavailable = products.filter(item => item.status !== 'ready' || item.publication_ready === false || item.publication_readiness?.ready_for_publication === false)
  if (unavailable.length) return ElMessage.warning(`所选产品中有 ${unavailable.length} 个尚未满足上架资料要求，请补齐或取消勾选`)
  router.push({
    path: '/catalog/ozon/publish',
    query: { products: products.map(item => item.id).join(','), source: 'pod' },
  })
}
async function openWbExport(product?: any) {
  const ids = product ? [product.id] : selected.value.map(item => item.id)
  if (!ids.length) return ElMessage.warning('请先勾选要发布的 POD 产品')
  wbForm.product_ids = ids; wbOpen.value = true; wbLoading.value = true
  try {
    const [templates, stores, exports, ...products] = await Promise.all([api.get<any>('/pod/wb/templates'), api.get<any>('/stores'), api.get<any>('/pod/wb/exports'), ...ids.map(id => api.get<any>(`/pod/library/products/${id}`))])
    wbTemplates.value = templates.items || []; wbStores.value = (stores.items || []).filter((row: any) => ['wb', 'wildberries'].includes(String(row.platform).toLowerCase()) && row.enabled); wbExports.value = exports.items || []
    wbVariantRows.value = products.flatMap((product: any) => (product.variants || []).filter((variant: any) => variant.active).map((variant: any) => ({ ...variant, product_name: product.name || product.sku })))
    wbForm.variant_ids = wbVariantRows.value.map(row => row.id)
    if (!wbForm.template_id && wbTemplates.value.length) wbForm.template_id = wbTemplates.value[0].id
    if (!wbForm.store_id && wbStores.value.length) wbForm.store_id = wbStores.value[0].id
  } catch (error: any) { ElMessage.error(error?.message || 'WB 发布资料读取失败') }
  finally { wbLoading.value = false }
}
function selectWbTemplateFile(file: any) {
  wbTemplateFile.value = file.raw
  const filename = String(file.name || file.raw?.name || '')
  const preset = [
    { pattern: /毛毯/, subject_name: '毛毯', subject_id: 321 },
    { pattern: /桌布/, subject_name: '桌布', subject_id: 231 },
    { pattern: /浴帘/, subject_name: '浴帘', subject_id: 1479 },
  ].find(item => item.pattern.test(filename))
  if (preset) Object.assign(wbTemplateForm, { subject_name: preset.subject_name, subject_id: preset.subject_id })
  return false
}
async function uploadWbTemplate() {
  if (!wbTemplateFile.value || !wbTemplateForm.subject_name.trim() || !wbTemplateForm.subject_id) return ElMessage.warning('请选择模板并填写 WB 类目名称、类目 ID')
  const form = new FormData(); form.append('file', wbTemplateFile.value); form.append('subject_name', wbTemplateForm.subject_name.trim()); form.append('subject_id', String(wbTemplateForm.subject_id))
  const result = await api.upload<any>('/pod/wb/templates', form); wbTemplates.value.unshift(result.template); wbForm.template_id = result.template.id; wbTemplateFile.value = undefined; ElMessage.success('WB 类目模板已保存')
}
async function submitWbExport() {
  if (!wbForm.store_id || !wbForm.template_id || !wbForm.brand.trim() || !wbForm.price_cny) return ElMessage.warning('请完整填写店铺、类目模板、品牌和人民币售价')
  if (wbForm.variant_selection === 'selected' && !wbForm.variant_ids.length) return ElMessage.warning('请至少勾选一个颜色/尺码 SKU')
  wbSubmitting.value = true
  try { const result = await api.post<any>('/pod/wb/exports', wbForm); ElMessage.success('WB 表格生成任务已进入后台，可立即离开本页'); wbOpen.value = false; window.location.href = `/jobs?job=${result.job.id}` }
  catch (error: any) { ElMessage.error(error?.message || 'WB 导出任务创建失败') }
  finally { wbSubmitting.value = false }
}
async function addCategory() { const value = await ElMessageBox.prompt('输入新的产品分类名称', '新建分类', { confirmButtonText: '创建', cancelButtonText: '取消' }).catch(() => null); if (!value?.value.trim()) return; await api.post('/pod/library/categories', { name: value.value.trim() }); ElMessage.success('分类已创建'); await load(); await loadManagedCategories() }
async function renameCategory(row: any) { if (String(row.id).startsWith('legacy:')) return ElMessage.warning('历史分类请先在产品上重新归类'); const value = await ElMessageBox.prompt('输入新的分类名称', '重命名分类', { inputValue: row.name, confirmButtonText: '保存', cancelButtonText: '取消' }).catch(() => null); if (!value?.value.trim()) return; await api.patch(`/pod/library/categories/${row.id}`, { name: value.value.trim() }); ElMessage.success('分类已更新'); await load(); await loadManagedCategories() }
async function removeCategory(row: any) { if (String(row.id).startsWith('legacy:')) return ElMessage.warning('历史分类请先在产品上重新归类'); await ElMessageBox.confirm(`删除分类“${row.name}”？其中产品会移到未分类，产品和图片不会删除。`, '删除分类', { type: 'warning' }); await api.delete(`/pod/library/categories/${row.id}`); ElMessage.success('分类已删除'); await load(); await loadManagedCategories() }
onMounted(load)
</script>

<template>
  <div class="page-stack pod-library-page">
    <section class="metric-grid">
      <div class="metric-card" style="--metric-color:#1d64f2"><strong>{{ summary.products }}</strong><span>POD 产品</span></div><div class="metric-card" style="--metric-color:#7c5ce7"><strong>{{ summary.variants }}</strong><span>颜色尺码 SKU</span></div><div class="metric-card" style="--metric-color:#18a672"><strong>{{ summary.current_assets }}</strong><span>当前产品图片</span></div><div class="metric-card" style="--metric-color:#e89d1b"><strong>{{ summary.versions }}</strong><span>生产版本</span></div>
    </section>
    <section class="panel">
      <div class="panel-head pod-library-head"><div><h2>{{market==='US'?'Amazon 美国 POD 产品库':'POD 产品库'}}</h2><p>每个印花成品独立建档，颜色和尺码归入产品 SKU；合成完成后自动入库</p></div><div class="asset-health"><span>本机已索引 {{ summary.local_assets }}</span><span>OSS 已存 {{ summary.oss_assets }}</span></div></div>
      <div style="padding:16px 20px 0"><el-radio-group v-model="market" @change="changeMarket"><el-radio-button value="CN">现有 POD 产品</el-radio-button><el-radio-button value="US">Amazon 美国 POD</el-radio-button></el-radio-group><el-alert v-if="market==='US'" title="按具体产品分类筛选；未手动分类的产品按原货盘产品名称归类。分类与 Amazon 美国站上架页共用。" type="info" :closable="false" /></div><div class="toolbar catalog-toolbar pod-toolbar"><el-input v-model="search" clearable placeholder="产品名称、SKU、产品编码或供应商商品 ID" @keyup.enter="query" /><el-select v-model="supplier" clearable placeholder="全部供应商"><el-option label="HICUSTOM" value="HICUSTOM" /><el-option label="S2B" value="S2B" /><el-option label="历史混合来源" value="HICUSTOM/S2B" /></el-select><el-select v-model="category" clearable filterable placeholder="当前货盘全部分类"><el-option v-for="item in categories" :key="item.id" :label="`${item.name} (${item.count})`" :value="item.name" /></el-select><el-select v-model="status" clearable placeholder="全部状态"><el-option label="在用" value="ready" /><el-option label="待整理" value="draft" /><el-option label="已归档" value="archived" /></el-select><el-button type="primary" @click="query">查询</el-button><span class="grow" /><el-button v-if="market==='US'" type="success" @click="router.push('/catalog/amazon/publish')">Amazon 美国站上架</el-button><el-button v-else type="success" :disabled="!selected.length" @click="publishToOzon()">批量上架到 OZON（{{ selected.length }}）</el-button><el-button v-if="market!=='US'" type="success" plain :disabled="!selected.length" @click="openWbExport()">发布到 WB</el-button><el-button :disabled="!selected.length" @click="batchCategory">批量分类</el-button><el-button @click="openCategoryManager">管理分类</el-button></div>
      <el-table v-loading="loading" :data="items" row-key="id" @selection-change="selected = $event" @row-click="show"><el-table-column type="selection" width="46" /><el-table-column label="产品图" width="92"><template #default="s"><el-image v-if="s.row.thumbnail_url" class="pod-product-thumb" :src="s.row.thumbnail_url" fit="cover" lazy /><div v-else class="pod-product-thumb placeholder">无图</div></template></el-table-column><el-table-column label="产品与编号" min-width="270"><template #default="s"><b>{{ s.row.name || '未命名 POD 产品' }}</b><small class="table-sub mono">{{ s.row.sku }} · {{ s.row.group_code }}</small><small class="table-sub">分类：{{ s.row.product_category || '未分类' }}</small></template></el-table-column><el-table-column prop="supplier" label="供应商" width="130" /><el-table-column prop="supplier_product_id" label="供应商商品" width="130" /><el-table-column prop="variant_count" label="颜色尺码 SKU" width="110" /><el-table-column label="当前产品图" width="125"><template #default="s"><span>{{ s.row.current_asset_count }} 张</span><small class="table-sub">本机 {{ s.row.local_asset_count }} / OSS {{ s.row.oss_asset_count }}</small></template></el-table-column><el-table-column label="产品状态" min-width="170"><template #default="s"><el-tag :type="s.row.library_state === 'ready' ? 'success' : s.row.library_state === 'archived' ? 'info' : 'warning'">{{ libraryStateLabel[s.row.library_state] || s.row.library_state }}</el-tag><small class="table-sub" :class="s.row.production_ready ? 'ready-text' : 'missing-text'">生产资料 {{ s.row.production_completeness }}%</small><small class="table-sub" :class="s.row.publication_ready ? 'ready-text' : 'missing-text'">上架资料 {{ s.row.publication_completeness }}%</small></template></el-table-column><el-table-column label="更新时间" width="170"><template #default="s">{{ formatDate(s.row.updated_at) }}</template></el-table-column><el-table-column label="操作" width="90"><template #default="s"><el-button link type="primary" @click.stop="show(s.row)">详情</el-button></template></el-table-column></el-table>
      <div class="pod-pagination"><span>共 {{ total }} 个产品 · {{ totalPages }} 页</span><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :total="total" :page-sizes="[25, 50, 100, 200]" layout="sizes, prev, pager, next" @change="load" /></div>
    </section>

    <el-drawer v-model="drawer" size="82%" :title="detail?.name || detailTitle" destroy-on-close>
      <div v-if="detailLoading" class="detail-loading"><el-skeleton :rows="10" animated /></div>
      <template v-else-if="detail">
        <div class="drawer-actions top"><el-button type="primary" :loading="supplierRefreshing" @click="refreshSupplierFacts">从供应商更新资料</el-button><el-button v-if="detail.source_type!=='pod_amazon'" @click="openExactEdit">人工补充资料</el-button><el-button @click="openFolder">打开产品文件夹</el-button><el-button @click="restore">从 OSS 恢复到本机</el-button><el-button v-if="detail.source_type==='pod_amazon'" type="success" @click="router.push('/catalog/amazon/publish')">Amazon 美国站上架</el-button><el-button v-if="detail.source_type!=='pod_amazon'" type="success" @click="publishToOzon(detail)">上架到 OZON</el-button><el-button v-if="detail.source_type!=='pod_amazon'" type="success" plain @click="openWbExport(detail)">发布到 WB</el-button><span class="grow" /><el-button v-if="detail.status !== 'archived'" @click="setProductStatus('archived')">归档产品</el-button><el-button v-else @click="setProductStatus('ready')">恢复使用</el-button></div>
        <div class="readiness-pair"><section class="readiness-card" :class="{ ready: detail.production_readiness?.ready_for_production }"><div><strong>{{ detail.production_readiness?.ready_for_production ? '可再次生产' : '生产资料还需补齐' }}</strong><span>{{ detail.production_readiness?.completeness_percent || 0 }}%</span></div><p v-if="detail.production_readiness?.blocking?.length">缺少：{{ detail.production_readiness.blocking.join('、') }}</p><p v-else>{{ detail.production_readiness?.can_rebuild_supplier_product ? '供应商图库为空时也可重新上传素材并重建生产产品。' : '当前供应商产品可继续使用。' }}</p></section><section class="readiness-card" :class="{ ready: detail.publication_readiness?.ready_for_publication }"><div><strong>{{ detail.publication_readiness?.ready_for_publication ? '可生成并发布' : '上架资料还需补齐' }}</strong><span>{{ detail.publication_readiness?.completeness_percent || 0 }}%</span></div><p v-if="detail.publication_readiness?.blocking?.length">缺少：{{ detail.publication_readiness.blocking.join('、') }}</p><p v-else>{{ detail.source_type==='pod_amazon' ? '可进入 Amazon 发布页面；资料核验和预检通过后才能正式提交。' : '可进入发布引擎；提交前仍会读取 OZON 实时属性并校验。' }}</p></section></div>
        <el-tabs v-model="detailTab" class="pod-detail-tabs">
          <el-tab-pane label="上架资料" name="overview">
