ail.source_snapshot?.sizes?.length || 0 }} 个</el-descriptions-item><el-descriptions-item label="库存 SKU">{{ detail.source_snapshot?.stock_info?.length || 0 }} 个</el-descriptions-item><el-descriptions-item label="供应商参考价">{{ showValue(detail.source_snapshot?.prices?.price, ' CNY') }}</el-descriptions-item><el-descriptions-item label="产地">{{ detail.source_snapshot?.produce_area || detail.source_snapshot?.produce_country || '-' }}</el-descriptions-item><el-descriptions-item label="仓库">{{ detail.source_snapshot?.warehouse_name || '-' }}</el-descriptions-item><el-descriptions-item label="供应商名称" :span="2">{{ detail.source_snapshot?.supplier_name || detail.supplier || '-' }}</el-descriptions-item></el-descriptions></el-tab-pane>
