    <el-dialog v-model="categoryOpen" title="POD 产品分类" width="680"><div class="category-actions"><el-button type="primary" @click="addCategory">新建分类</el-button><span>管理全部货盘的内部分类；分类变更同时用于 POD 产品库和 Amazon 选品。</span></div><el-table v-loading="categoryLoading" :data="managedCategories"><el-table-column prop="name" label="分类名称" /><el-table-column prop="count" label="产品数" width="100" /><el-table-column label="操作" width="170"><template #default="s"><el-button link @click="renameCategory(s.row)">重命名</el-button><el-button link type="danger" @click="removeCategory(s.row)">删除</el-button></template></el-table-column></el-table><template #footer><el-button @click="categoryOpen = false">关闭</el-button></template></el-dialog>
    <el-dialog v-model="wbOpen" title="POD 产品发布到 WB（生成批量上传表格）" width="920"><div v-loading="wbLoading"><el-alert :title="`本次已选 ${wbForm.product_ids.length} 个产品。任务在后台逐个生成文案，关闭页面或重启后可继续。当前不会调用 WB 写入接口。`" type="info" :closable="false" /><el-form label-width="125" class="wb-export-form"><el-form-item label="WB 店铺"><el-select v-model="wbForm.store_id" placeholder="请选择已启用的 WB 店铺"><el-option v-for="row in wbStores" :key="row.id" :label="row.name" :value="row.id" /></el-select><span v-if="!wbStores.length" class="missing-text">接口设置中还没有启用的 WB 店铺</span></el-form-item><el-form-item label="类目模板"><el-select v-model="wbForm.template_id" placeholder="请选择 WB 官方模板"><el-option v-for="row in wbTemplates" :key="row.id" :label="`${row.subject_name} · ${row.filename}`" :value="row.id" /></el-select></el-form-item><el-form-item label="品牌 / 售价"><el-input v-model="wbForm.brand" placeholder="WB 品牌名称" /><el-input-number v-model="wbForm.price_cny" :min="0.01" :precision="2" placeholder="人民币售价" /><span>CNY，不换算卢布</span></el-form-item><el-form-item label="导出 SKU"><el-radio-group v-model="wbForm.variant_selection"><el-radio-button value="all">全部颜色尺码</el-radio-button><el-radio-button value="selected">指定 SKU</el-radio-button><el-radio-button value="largest_one">最大 1 个</el-radio-button><el-radio-button value="largest_two">最大 2 个</el-radio-button><el-radio-button value="largest_three">最大 3 个</el-radio-button></el-radio-group></el-form-item><el-form-item v-if="wbForm.variant_selection === 'selected'" label="勾选规格"><el-checkbox-group v-model="wbForm.variant_ids" class="wb-variant-picker"><el-checkbox v-for="row in wbVariantRows" :key="row.id" :value="row.id" border><b>{{ row.product_name }}</b><span>{{ row.color || '无颜色' }} · {{ row.size || row.specification || '无尺码' }} · {{ row.sku }}</span></el-checkbox></el-checkbox-group></el-form-item><el-form-item label="本次文案要求"><el-input v-model="wbForm.requirement" type="textarea" :rows="3" placeholder="每次发布都会重新生成俄文标题、描述和模板属性" /></el-form-item></el-form><el-divide